  *{box-sizing:border-box;margin:0;padding:0}
  html{scroll-behavior:smooth}
  body{
    font-family:'Archivo',Helvetica,Arial,sans-serif;
    background:var(--white);
    color:var(--black);
    line-height:1.55;
  }

  /* ---------- Mondrian grid header ---------- */
  .grid-hero{
    display:grid;
    grid-template-columns:1.1fr 2fr 1fr;
    grid-template-rows:minmax(120px,22vh) minmax(200px,38vh) minmax(120px,20vh);
    border-bottom:var(--line) solid var(--black);
    border-right:var(--line) solid var(--black);
  }
  .cell{border-left:var(--line) solid var(--black);border-top:var(--line) solid var(--black)}
  .cell.red{background:var(--red)}
  .cell.blue{background:var(--blue)}
  .cell.yellow{background:var(--yellow)}
  .hero-title{
    grid-column:1/3;grid-row:2;
    padding:clamp(1rem,4vw,3rem);
    display:flex;flex-direction:column;justify-content:center;
  }
  h1{
    font-family:'Archivo Black','Archivo',sans-serif;
    font-size:clamp(1.6rem,4.5vw,3.4rem);
    line-height:1.05;
    text-transform:uppercase;
    letter-spacing:-0.01em;
  }
  .hero-sub{margin-top:1rem;font-weight:600;font-size:clamp(.95rem,1.6vw,1.15rem)}
  .hero-sub span{display:block;font-weight:400}

  /* ---------- content ---------- */
  main{max-width:1100px;margin:0 auto;padding:clamp(1.5rem,4vw,3rem)}
  section{margin-bottom:clamp(2rem,5vw,3.5rem)}
  h2{
    font-family:'Archivo Black','Archivo',sans-serif;
    text-transform:uppercase;
    font-size:clamp(1.1rem,2.4vw,1.6rem);
    border-bottom:var(--line) solid var(--black);
    display:inline-block;
    padding:0 .35rem .35rem 0;
    margin-bottom:1.25rem;
  }
  p{max-width:62ch;font-size:clamp(1rem,1.5vw,1.15rem);margin-bottom:.9rem}
  strong{font-weight:800}

  /* three principle blocks */
  .blocks{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--line)}
  .blocks article{
    border:var(--line) solid var(--black);
    padding:1.25rem 1.25rem 1.5rem;
    color:var(--white);
  }
  .blocks article h3{font-family:'Archivo Black',sans-serif;text-transform:uppercase;font-size:1.05rem;margin-bottom:.5rem}
  .blocks article p{color:inherit;font-size:.98rem;max-width:none}
  .blocks .b-red{background:var(--red)}
  .blocks .b-blue{background:var(--blue)}
  .blocks .b-yellow{background:var(--yellow);color:var(--black)}
  .blocks .b-yellow p{color:var(--black)}

  /* picture description strip */
  .picture{
    display:grid;
    grid-template-columns:repeat(auto-fit,minmax(180px,1fr));
    border:var(--line) solid var(--black);
  }
  .picture>div{padding:1.1rem;border-left:var(--line) solid var(--black)}
  .picture>div:first-child{border-left:none}
  .picture .swatch{width:2.4rem;height:2.4rem;border:6px solid var(--black);margin-bottom:.7rem}
  .picture h3{font-weight:800;text-transform:uppercase;font-size:.9rem;margin-bottom:.25rem}

